¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â

  async findAll(query: QueryPayrollDto) {
    const filter: FilterQuery<Payroll> = {};

    if (query.teacherId) filter.teacherId = new Types.ObjectId(query.teacherId);
    if (query.status) filter.status = query.status;
    if (query.fromDate || query.toDate) {
      filter.periodStart = {};
      if (query.fromDate) filter.periodStart.$gte = new Date(query.fromDate);
      if (query.toDate) filter.periodStart.$lte = new Date(query.toDate);
    }

    const page = Number(query.page) || 1;
    const limit = Math.min(Number(query.limit) || 20, 100);
    const skip = (page - 1) * limit;
    const sort = query.sort || '-createdAt';

    const [data, total] = await Promise.all([
      this.payrollModel
        .find(filter)
        .sort(sort)
        .skip(skip)
        .limit(limit)
        .populate('teacherId', 'fullName email phone')
        .populate('createdBy', 'fullName')
        .populate('approvedBy', 'fullName')
        .lean(),
      this.payrollModel.countDocuments(filter),
    ]);

    return {
      data,
      meta: { total, page, limit, totalPages: Math.ceil(total / limit) },
    };
  }

  async findById(id: string, actor?: JwtPayload): Promise<PayrollDocument> {
    const payroll = await this.payrollModel
      .findById(id)
      .populate('teacherId', 'fullName email phone')
      .populate('createdBy', 'fullName')
      .populate('approvedBy', 'fullName')
      .populate('paidBy', 'fullName');

    if (!payroll) throw new NotFoundException('BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œn tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i');

    // TEACHER can only view their own payroll
    if (actor?.role === Role.TEACHER && payroll.teacherId?.toString() !== actor.sub) {
      throw new ForbiddenException('BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡n khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng cÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³ quyÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Ân xem bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng nÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â y');
    }
    return payroll;
  }

  /**
   * LÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¥y danh sÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ch items cÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â§a 1 payroll.
   * FIX PERF: Thay thÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¿ N+1 .populate() chain bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â±ng aggregation $lookup.
   * 100 items: 301 queries ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ 1 aggregation.
   */
  async getPayrollItems(payrollId: string, actor?: JwtPayload): Promise<any[]> {
    // Verify ownership for TEACHER
    if (actor?.role === Role.TEACHER) {
      const payroll = await this.payrollModel.findById(payrollId).lean();
      if (!payroll || payroll.teacherId?.toString() !== actor.sub) {
        throw new ForbiddenException('BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡n khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng cÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³ quyÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Ân xem bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng nÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â y');
      }
    }

    return this.payrollItemModel.aggregate([
      { $match: { payrollId: new Types.ObjectId(payrollId) } },
      { $sort: { sessionDate: 1 } },
      {
        $lookup: {
          from: 'sessions',
          localField: 'sessionId',
          foreignField: '_id',
          as: 'sessionId',
          pipeline: [
            { $project: { scheduledDate: 1, scheduledStartTime: 1, scheduledEndTime: 1, status: 1 } },
          ],
        },
      },
      { $unwind: { path: '$sessionId', preserveNullAndEmptyArrays: true } },
      {
        $lookup: {
          from: 'classrooms',
          localField: 'classId',
          foreignField: '_id',
          as: 'classId',
          pipeline: [{ $project: { name: 1, code: 1 } }],
        },
      },
      { $unwind: { path: '$classId', preserveNullAndEmptyArrays: true } },
      {
        $lookup: {
          from: 'students',
          localField: 'studentId',
          foreignField: '_id',
          as: 'studentId',
          pipeline: [{ $project: { fullName: 1, studentCode: 1 } }],
        },
      },
      { $unwind: { path: '$studentId', preserveNullAndEmptyArrays: true } },
    ]);
  }

