¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â

  async update(id: string, dto: UpdatePayrollDto): Promise<PayrollDocument> {
    const payroll = await this.payrollModel.findById(id);
    if (!payroll) throw new NotFoundException('BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œn tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i');

    if (payroll.status !== PayrollStatus.DRAFT) {
      throw new BadRequestException('ChÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â° sÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â­a ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â£c bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng DRAFT');
    }

    if (dto.bonusAmount !== undefined) payroll.bonusAmount = dto.bonusAmount;
    if (dto.deductionAmount !== undefined) payroll.deductionAmount = dto.deductionAmount;
    if (dto.notes !== undefined) payroll.notes = dto.notes;

    // FIX BUG #8: Floor netAmount tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i 0 ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â thÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ng nhÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¥t vÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Âºi StaffPayroll
    payroll.netAmount = Math.max(
      0,
      payroll.grossAmount +
        payroll.adjustmentAmount +
        payroll.bonusAmount -
        payroll.deductionAmount,
    );

    try {
      return await payroll.save();
    } catch (err) {
      this.throwIfVersionConflict(err);
    }
  }

  /** ÃƒÆ’Ã¢â‚¬Å¾Ãƒâ€šÃ‚ÂiÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Âu chÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â°nh 1 item (chÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â° khi payroll DRAFT) */
  async adjustItem(
    payrollId: string,
    itemId: string,
    dto: AdjustPayrollItemDto,
    adjustedBy: string,
  ): Promise<PayrollItemDocument> {
    const mongoSession = await this.connection.startSession();
    mongoSession.startTransaction();

    try {
      const payroll = await this.payrollModel.findById(payrollId).session(mongoSession);
      if (!payroll) {
        throw new NotFoundException(
          'BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œn tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i',
        );
      }
      if (payroll.status !== PayrollStatus.DRAFT) {
        throw new BadRequestException(
          'ChÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â° ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“iÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Âu chÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â°nh ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â£c khi DRAFT',
        );
      }

      const item = await this.payrollItemModel
        .findOne({
          _id: new Types.ObjectId(itemId),
          payrollId: new Types.ObjectId(payrollId),
        })
        .session(mongoSession);
      if (!item) {
        throw new NotFoundException(
          'Item khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œn tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i trong payroll',
        );
      }

      const oldPayout = item.adjustedPayout;
      const oldStatus = item.status;
      item.adjustedPayout = dto.adjustedPayout;
      if (dto.adjustmentReason !== undefined) item.adjustmentReason = dto.adjustmentReason;
      if (dto.status) item.status = dto.status;

      // Ghi audit trail ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°u giÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ trÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¹ cÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â© trÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Âºc khi ghi ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¨
      if (oldPayout !== dto.adjustedPayout) {
        item.adjustmentHistory = [
          ...(item.adjustmentHistory || []),
          {
            adjustedBy,
            fromAmount: oldPayout,
            toAmount: dto.adjustedPayout,
            reason: dto.adjustmentReason,
            changedAt: new Date(),
          },
        ];
      }

      await item.save({ session: mongoSession });

      const newStatus = item.status;
      const isExcluded = (status?: PayrollItemStatus) =>
        status === PayrollItemStatus.EXCLUDED;
      const sessionId = item.sessionId.toString();

      // Excluded item is released so it can be paid in a later payroll cycle.
      if (!isExcluded(oldStatus) && isExcluded(newStatus)) {
        await this.sessionsService.unmarkTeacherPaid([sessionId], mongoSession);
      }

      // If item is re-included while payroll is still DRAFT, claim it back.
      if (isExcluded(oldStatus) && !isExcluded(newStatus)) {
        await this.sessionsService.claimTeacherPaid([sessionId], mongoSession);
      }

      // Recalc payroll totals
      await this.recalcPayrollTotals(payrollId, mongoSession);
      await mongoSession.commitTransaction();
      return item;
    } catch (err) {
      await mongoSession.abortTransaction();
      this.throwIfVersionConflict(err);
    } finally {
      mongoSession.endSession();
    }
  }

