  private async resolveActiveBankAccountId(
    requestedBankAccountId: string | undefined,
    mongoSession: ClientSession,
    context: string,
  ): Promise<string> {
    const BankAccountModel = this.connection.model('BankAccount');

    if (requestedBankAccountId) {
      if (!Types.ObjectId.isValid(requestedBankAccountId)) {
        throw new BadRequestException('bankAccountId khong hop le');
      }

      const requested = await BankAccountModel.findOne({
        _id: new Types.ObjectId(requestedBankAccountId),
        status: 'ACTIVE',
      })
        .select({ _id: 1 })
        .session(mongoSession)
        .lean();

      if (!requested) {
        throw new BadRequestException('Tai khoan ngan hang khong ton tai hoac khong ACTIVE');
      }
      return (requested as any)._id.toString();
    }

    const fallback = await BankAccountModel.findOne({ status: 'ACTIVE' })
      .sort({ isPrimary: -1, createdAt: -1 })
      .select({ _id: 1 })
      .session(mongoSession)
      .lean();

    if (!fallback) {
      throw new BadRequestException(
        `Khong co tai khoan ngan hang ACTIVE de ghi nhan giao dich ${context}`,
      );
    }

    return (fallback as any)._id.toString();
  }

  async remove(id: string): Promise<void> {
    const payroll = await this.payrollModel.findById(id);
    if (!payroll) throw new NotFoundException('BÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng khÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â´ng tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œn tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡i');
    if (payroll.status !== PayrollStatus.DRAFT) {
      throw new BadRequestException('ChÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â° xÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³a ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â£c bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng DRAFT');
    }

    // FIX BUG #5: Unmark TÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¤T CÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¢ items (kÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€ Ã¢â‚¬â„¢ cÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ EXCLUDED) khi xÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³a.
    // TrÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡nh sessions EXCLUDED bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¹ lock isTeacherPaid=true vÃƒÆ’Ã¢â‚¬Å¾Ãƒâ€šÃ‚Â©nh viÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦n.
    const items = await this.payrollItemModel.find({
      payrollId: payroll._id,
      status: PayrollItemStatus.INCLUDED,
    });
    const sessionIds = items.map((i) => i.sessionId.toString());
    if (sessionIds.length > 0) {
      await this.sessionsService.unmarkTeacherPaid(sessionIds);
    }

    await this.payrollItemModel.deleteMany({ payrollId: payroll._id });
    await this.payrollModel.findByIdAndDelete(id);
  }

