¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢Ãƒâ€šÃ‚Â

  /**
   * TÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡o bÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ng lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng cho tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¥t cÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â£ GV cÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â³ buÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢i dÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡y trong kÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â³.
   * GÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Âi khi ACCOUNTING muÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“n tÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚ÂºÃƒâ€šÃ‚Â¡o ÃƒÆ’Ã¢â‚¬Å¾ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“ÃƒÆ’Ã‚Â¡Ãƒâ€šÃ‚Â»Ãƒâ€šÃ‚Â£t lÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â Ãƒâ€šÃ‚Â¡ng hÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â ng thÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ng.
   */
  async bulkGenerate(
    periodStart: string,
    periodEnd: string,
    createdBy: string,
  ): Promise<{ created: number; skipped: number; errors: string[] }> {
    const from = normalizeDate(periodStart);
    const to = normalizeDate(periodEnd);
    const cutoffExclusive = new Date(to);
    cutoffExclusive.setUTCDate(cutoffExclusive.getUTCDate() + 1); // include full periodEnd day
    if (to < from) {
      throw new BadRequestException('Ngay ket thuc khong duoc truoc ngay bat dau');
    }

    // Get distinct teachers with finalized sessions in period
    const SessionModel = this.connection.model('Session');

    const teacherIds: Types.ObjectId[] = await SessionModel.distinct('teacherId', {
      status: 'FINALIZED',
      isTeacherPaid: false,
      hasTeachingReport: true,
      'confirmation.finalizedAt': {
        $lt: cutoffExclusive,
      },
    });

    let created = 0;
    const skipped: number[] = [];
    const errors: string[] = [];

    for (const tid of teacherIds) {
      try {
        await this.generate(
          {
            teacherId: tid.toString(),
            periodStart,
            periodEnd,
          },
          createdBy,
        );
        created++;
      } catch (err) {
        if (
          err instanceof BadRequestException &&
          /ton tai/i.test((err as BadRequestException).message || '')
        ) {
          skipped.push(1);
        } else {
          errors.push(`Teacher ${tid}: ${(err as Error).message}`);
        }
      }
    }

    return { created, skipped: skipped.length, errors };
  }

